// Generated by scripts/build-sw.mjs from scripts/sw-template.js during `npm run build`.
// App files are served cache-first; a new build hash installs a new worker that the
// History "Check for Updates" action activates. Workout data lives in IndexedDB and
// localStorage and is never touched here.
const CACHE_NAME = '__CACHE_NAME__';
const PRECACHE_URLS = __PRECACHE_URLS__;
const ROUTE_SHELLS = ['/routine/', '/history/', '/workout/'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) =>
      Promise.all(
        PRECACHE_URLS.map(async (url) => {
          const response = await fetch(new Request(url, { cache: 'reload' }));
          if (!response.ok) throw new Error(`Precache failed for ${url}`);
          await cache.put(url, response);
        }),
      ),
    ),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key.startsWith('maxsnr-') && key !== CACHE_NAME)
            .map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') event.waitUntil(self.skipWaiting());
});

function shellFor(pathname) {
  if (pathname === '/' || pathname === '/index.html') return '/';
  return ROUTE_SHELLS.find((shell) =>
    [shell, shell.slice(0, -1), `${shell}index.html`].includes(pathname),
  );
}

async function respond(request, url) {
  const cache = await caches.open(CACHE_NAME);
  const shell = request.mode === 'navigate' ? shellFor(url.pathname) : null;
  const cached = await cache.match(shell || url.pathname);
  if (cached) return cached;
  try {
    return await fetch(request);
  } catch (error) {
    if (request.mode !== 'navigate') throw error;
    return (await cache.match('/')) || Response.error();
  }
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;
  event.respondWith(respond(request, url));
});
